const std = @import("std");
const C = @import("clues.zig");
const L = @import("line_solver.zig");
const P = @import("propagation.zig");
const Q = @import("search.zig");
const R = @import("render.zig");
const Given = struct { row: usize, column: usize, value: L.Cell };
const RawGiven = struct { row: usize, column: usize, value: u8 };
const Puzzle = struct { name: []const u8, width: usize, height: usize, row_lines: C.Strings, column_lines: C.Strings, given_lines: []const RawGiven, answer_lines: ?C.Strings, rows: C.Clues = &.{}, columns: C.Clues = &.{}, givens: []const Given = &.{}, answer: ?P.Grid = null };
const Status = enum { contradiction, none, unique, multiple };
const Difficulty = enum { easy, medium, hard, unavailable };
fn difficultyText(value: Difficulty) []const u8 { return if (value == .unavailable) "-" else @tagName(value); }
fn readBlocks(text: []const u8) []const C.Strings { var blocks: std.ArrayList(C.Strings) = .empty; var block: std.ArrayList([]const u8) = .empty; var inside = false;
    for (C.lines(text)) |line| { if (!inside) { if (line.len > 0 and line[0] != '#') { inside = true; block = .empty; C.append([]const u8, &block, line); } } else if (C.eq(line, "END")) { C.append(C.Strings, &blocks, block.items); inside = false; } else C.append([]const u8, &block, line); } return blocks.items;
}
fn parsePuzzle(block: C.Strings) *Puzzle { const size = C.split(block[1], ' '); var column_at: usize = 3; while (!C.eq(block[column_at], "COLUMNS")) column_at += 1; var position = column_at + 1; const first = position; while (position < block.len and C.isClueLine(block[position])) position += 1; const column_lines = block[first..position]; var givens: std.ArrayList(RawGiven) = .empty;
    while (position < block.len and std.mem.startsWith(u8, block[position], "GIVEN ")) : (position += 1) { const fields = C.split(block[position], ' '); C.append(RawGiven, &givens, .{ .row = C.number(fields[1]), .column = C.number(fields[2]), .value = fields[3][0] }); }
    return C.create(Puzzle, .{ .name = block[0][7..], .width = C.number(size[1]), .height = C.number(size[2]), .row_lines = block[3..column_at], .column_lines = column_lines, .given_lines = givens.items, .answer_lines = if (position < block.len) block[position + 1..] else null });
}
fn validName(name: []const u8) bool { if (name.len == 0 or name.len > 20) return false; for (name) |ch| { if (!((ch >= 'a' and ch <= 'z') or (ch >= '0' and ch <= '9') or ch == '_')) return false; } return true; }
fn gridFromText(texts: C.Strings) P.Grid { var grid: P.Grid = .{ .width = texts[0].len, .height = texts.len }; for (texts, 0..) |text, r| { for (text, 0..) |ch, c| grid.set(r, c, R.charState(ch)); } return grid; }
fn validStates(text: []const u8, allow_unknown: bool) bool { for (text) |ch| { if (ch != '#' and ch != '.' and !(allow_unknown and ch == '?')) return false; } return true; }
fn validate(puzzle: *Puzzle, earlier: std.StringHashMapUnmanaged(void)) ?[]const u8 {
    if (!validName(puzzle.name)) return "bad name"; if (earlier.contains(puzzle.name)) return "duplicate name"; if (puzzle.width < 1 or puzzle.width > 30 or puzzle.height < 1 or puzzle.height > 30) return "bad size";
    if (puzzle.row_lines.len != puzzle.height) return C.fmt("row count {d} expected {d}", .{ puzzle.row_lines.len, puzzle.height }); if (puzzle.column_lines.len != puzzle.width) return C.fmt("column count {d} expected {d}", .{ puzzle.column_lines.len, puzzle.width });
    const rows = C.alloc(C.Clue, puzzle.height); const columns = C.alloc(C.Clue, puzzle.width);
    for (puzzle.row_lines, rows, 1..) |text, *clue, i| { clue.* = C.parse(text) orelse return C.fmt("bad clue row {d}", .{i}); if (!C.fits(clue.*, puzzle.width)) return C.fmt("row {d} too long", .{i}); }
    for (puzzle.column_lines, columns, 1..) |text, *clue, i| { clue.* = C.parse(text) orelse return C.fmt("bad clue column {d}", .{i}); if (!C.fits(clue.*, puzzle.height)) return C.fmt("column {d} too long", .{i}); }
    var row_total: usize = 0; var column_total: usize = 0; for (rows) |clue| row_total += C.total(clue); for (columns) |clue| column_total += C.total(clue); if (row_total != column_total) return C.fmt("total mismatch rows={d} columns={d}", .{ row_total, column_total }); puzzle.rows = rows; puzzle.columns = columns;
    var taken = [_]bool{false} ** 900; const givens = C.alloc(Given, puzzle.given_lines.len); for (puzzle.given_lines, givens, 1..) |raw, *given, k| { if (raw.row < 1 or raw.row > puzzle.height or raw.column < 1 or raw.column > puzzle.width or (raw.value != '#' and raw.value != '.')) return C.fmt("bad given {d}", .{k}); const slot = (raw.row - 1) * puzzle.width + raw.column - 1; if (taken[slot]) return C.fmt("duplicate given {d}", .{k}); taken[slot] = true; given.* = .{ .row = raw.row - 1, .column = raw.column - 1, .value = R.charState(raw.value) }; } puzzle.givens = givens;
    if (puzzle.answer_lines) |texts| { if (texts.len != puzzle.height) return "bad answer"; for (texts) |text| { if (text.len != puzzle.width or !validStates(text, true)) return "bad answer"; } puzzle.answer = gridFromText(texts); } return null;
}
const Logical = struct { grid: P.Grid, propagation: P.Result };
fn logicalSolve(allocator: std.mem.Allocator, rows: C.Clues, columns: C.Clues, givens: []const Given, precise: bool) Logical { var grid: P.Grid = .{ .width = columns.len, .height = rows.len }; for (givens) |given| grid.set(given.row, given.column, given.value); var row_marks = [_]bool{false} ** 30; var column_marks = [_]bool{false} ** 30; @memset(row_marks[0..rows.len], true); @memset(column_marks[0..columns.len], true); const propagation = P.propagate(allocator, &grid, rows, columns, precise, &row_marks, &column_marks); return .{ .grid = grid, .propagation = propagation }; }
fn solvingResult(grid: *const P.Grid, propagation: P.Result) []const u8 { if (propagation.conflict) |step| return C.fmt("contradiction at={s}", .{step.label()}); return if (grid.known() == grid.width * grid.height) "solved" else "stuck"; }
const Analysis = struct {
    arena: std.heap.ArenaAllocator, simple_grid: P.Grid, logic_grid: P.Grid, simple: P.Result, logic: P.Result, search: ?Q.Search, solutions: []const P.Grid, status: Status, difficulty: Difficulty, line_solves: usize, guesses: usize, max_depth: usize,
    fn deinit(self: *Analysis) void { self.arena.deinit(); }
};
fn analyze(rows: C.Clues, columns: C.Clues, givens: []const Given) Analysis {
    var arena = std.heap.ArenaAllocator.init(C.backing); const allocator = arena.allocator(); const simple = logicalSolve(allocator, rows, columns, givens, false); const logic = logicalSolve(allocator, rows, columns, givens, true); var search: ?Q.Search = null; var solutions: []const P.Grid = &.{}; var status: Status = undefined; var difficulty: Difficulty = .unavailable;
    if (logic.propagation.conflict != null) status = .contradiction else if (logic.grid.known() == rows.len * columns.len) { status = .unique; const one = allocator.alloc(P.Grid, 1) catch @panic("allocation failed"); one[0] = logic.grid; solutions = one; difficulty = if (simple.propagation.conflict == null and simple.grid.known() == rows.len * columns.len) .easy else .medium; } else { var result: Q.Search = .{}; _ = result.run(allocator, &logic.grid, rows, columns, 1); solutions = result.solutions.items; status = switch (solutions.len) { 0 => .none, 1 => .unique, else => .multiple }; if (status == .unique) difficulty = .hard; search = result; }
    return .{ .arena = arena, .simple_grid = simple.grid, .logic_grid = logic.grid, .simple = simple.propagation, .logic = logic.propagation, .search = search, .solutions = solutions, .status = status, .difficulty = difficulty, .line_solves = logic.propagation.steps.items.len + (if (search) |result| result.line_solves else @as(usize, 0)), .guesses = if (search) |result| result.guesses.items.len else 0, .max_depth = if (search) |result| result.max_depth else 0 };
}
fn clueStatistics(rows: C.Clues, columns: C.Clues) []const u8 { var row_blocks: usize = 0; var column_blocks: usize = 0; var filled: usize = 0; var maximum: usize = 0; var fixed: usize = 0; for (rows) |clue| { row_blocks += clue.len; filled += C.total(clue); if (clue.len == 0 or C.span(clue) == C.int(columns.len)) fixed += 1; for (clue) |length| maximum = @max(maximum, length); } for (columns) |clue| { column_blocks += clue.len; if (clue.len == 0 or C.span(clue) == C.int(rows.len)) fixed += 1; for (clue) |length| maximum = @max(maximum, length); } return C.fmt("row_blocks={d} column_blocks={d} filled={d} max_block={d} fixed_lines={d}", .{ row_blocks, column_blocks, filled, maximum, fixed }); }
fn stepStatistics(propagation: P.Result) []const u8 { var productive: usize = 0; var idle: usize = 0; var best: usize = 0; var at: []const u8 = "-"; for (propagation.steps.items) |step| { if (step.contradiction) continue; if (step.gain > 0) productive += 1 else idle += 1; if (step.gain > best) { best = step.gain; at = step.label(); } } return C.fmt("productive={d} idle={d} best={d} at={s}", .{ productive, idle, best, at }); }
fn featuresText(grid: *const P.Grid) []const u8 {
    var seen = [_]bool{false} ** 900; var filled: usize = 0; var components: usize = 0; var largest: usize = 0; var min_row = grid.height; var min_column = grid.width; var max_row: usize = 0; var max_column: usize = 0;
    for (0..grid.height) |r| { for (0..grid.width) |c| { if (grid.get(r, c) != .filled) continue; filled += 1; min_row = @min(min_row, r); min_column = @min(min_column, c); max_row = @max(max_row, r); max_column = @max(max_column, c); const slot = r * grid.width + c; if (seen[slot]) continue; components += 1; var pending: [900]Q.Position = undefined; pending[0] = .{ .row = r, .column = c }; var count: usize = 1; var size: usize = 0; seen[slot] = true;
        while (count > 0) { count -= 1; const position = pending[count]; size += 1; const neighbors = [_][2]i64{ .{ C.int(position.row) - 1, C.int(position.column) }, .{ C.int(position.row) + 1, C.int(position.column) }, .{ C.int(position.row), C.int(position.column) - 1 }, .{ C.int(position.row), C.int(position.column) + 1 } }; for (neighbors) |next| { if (next[0] < 0 or next[1] < 0 or next[0] >= C.int(grid.height) or next[1] >= C.int(grid.width)) continue; const nr: usize = @intCast(next[0]); const nc: usize = @intCast(next[1]); const index = nr * grid.width + nc; if (grid.get(nr, nc) == .filled and !seen[index]) { seen[index] = true; pending[count] = .{ .row = nr, .column = nc }; count += 1; } } } largest = @max(largest, size);
    } }
    var symmetry: std.ArrayList([]const u8) = .empty; const names = [_][]const u8{ "lr", "ud", "rot180" }; for (names, 0..) |name, kind| { var matches = true; for (0..grid.height) |r| { for (0..grid.width) |c| { const mr = if (kind != 0) grid.height - 1 - r else r; const mc = if (kind != 1) grid.width - 1 - c else c; if (grid.get(r, c) != grid.get(mr, mc)) matches = false; } } if (matches) C.append([]const u8, &symmetry, name); }
    const bbox = if (filled == 0) "-" else C.fmt("{d},{d},{d},{d}", .{ min_row + 1, min_column + 1, max_row + 1, max_column + 1 }); return C.fmt("filled={d} components={d} largest={d} bbox={s} symmetry={s}", .{ filled, components, largest, bbox, if (symmetry.items.len == 0) "none" else C.join(symmetry.items, ",") });
}
fn unknownSummary(grid: *const P.Grid, is_row: bool) []const u8 { var parts: std.ArrayList([]const u8) = .empty; const lines = if (is_row) grid.height else grid.width; const length = if (is_row) grid.width else grid.height; for (0..lines) |i| { const cells = grid.line(is_row, i); var count: usize = 0; for (cells[0..length]) |state| { if (state == .unknown) count += 1; } if (count > 0) C.append([]const u8, &parts, C.fmt("{d}:{d}", .{ i + 1, count })); } return C.join(parts.items, " "); }
fn differing(first: *const P.Grid, second: *const P.Grid) []const Q.Position { var result: std.ArrayList(Q.Position) = .empty; for (0..first.height) |r| { for (0..first.width) |c| { if (first.get(r, c) != second.get(r, c)) C.append(Q.Position, &result, .{ .row = r, .column = c }); } } return result.items; }
fn firstDifference(first: *const P.Grid, second: *const P.Grid) Q.Position { for (0..first.height) |r| { for (0..first.width) |c| { if (first.get(r, c) != second.get(r, c)) return .{ .row = r, .column = c }; } } unreachable; }
fn numberList(numbers: []const usize) []const u8 { if (numbers.len == 0) return "-"; const parts = C.alloc([]const u8, numbers.len); for (numbers, parts) |number, *part| part.* = C.fmt("{d}", .{number}); return C.join(parts, ","); }
fn without(givens: []const Given, skipped: usize) []const Given { const result = C.alloc(Given, givens.len - 1); @memcpy(result[0..skipped], givens[0..skipped]); @memcpy(result[skipped..], givens[skipped + 1..]); return result; }
fn evaluateGivens(puzzle: *const Puzzle, status: Status) ?[]const u8 { if (puzzle.givens.len == 0 or status == .multiple) return null; var numbers: std.ArrayList(usize) = .empty; for (0..puzzle.givens.len) |i| { var other = analyze(puzzle.rows, puzzle.columns, without(puzzle.givens, i)); const accepted = if (status == .unique) other.status == .unique else other.status == .unique or other.status == .multiple; other.deinit(); if (accepted) C.append(usize, &numbers, i + 1); } return C.fmt("givens {s}={s}", .{ if (status == .unique) "redundant" else "blame", numberList(numbers.items) }); }
const Grade = struct { result: []const u8, lines: C.Lines };
fn gradeAnswer(puzzle: *const Puzzle, analysis: *const Analysis) Grade {
    const answer = &puzzle.answer.?; var rows: std.ArrayList(usize) = .empty; var columns: std.ArrayList(usize) = .empty; var givens: std.ArrayList(usize) = .empty;
    for (puzzle.rows, 0..) |clue, i| { const cells = answer.line(true, i); if (!L.hasPlacement(cells[0..puzzle.width], clue)) C.append(usize, &rows, i + 1); } for (puzzle.columns, 0..) |clue, i| { const cells = answer.line(false, i); if (!L.hasPlacement(cells[0..puzzle.height], clue)) C.append(usize, &columns, i + 1); }
    for (puzzle.givens, 1..) |given, i| { const state = answer.get(given.row, given.column); if (state != .unknown and state != given.value) C.append(usize, &givens, i); } const known = answer.known(); const mismatched = rows.items.len > 0 or columns.items.len > 0 or givens.items.len > 0; const partial = known < puzzle.width * puzzle.height; const result: []const u8 = if (partial) "partial" else if (mismatched) "wrong" else "correct"; var text: C.Text = .{}; text.add("answer result={s} known={d} rows={s} columns={s} givens={s}", .{ result, known, numberList(rows.items), numberList(columns.items), numberList(givens.items) });
    if (partial) { var extendable = false; if (!mismatched) { var extra: [900]Given = undefined; var count = puzzle.givens.len; @memcpy(extra[0..count], puzzle.givens); var taken = [_]bool{false} ** 900; for (puzzle.givens) |given| taken[given.row * puzzle.width + given.column] = true; for (0..puzzle.height) |r| { for (0..puzzle.width) |c| { const state = answer.get(r, c); if (state != .unknown and !taken[r * puzzle.width + c]) { extra[count] = .{ .row = r, .column = c, .value = state }; count += 1; } } } var other = analyze(puzzle.rows, puzzle.columns, extra[0..count]); extendable = other.status == .unique or other.status == .multiple; other.deinit(); } text.add(" extendable={s}", .{if (extendable) "yes" else "no"}); }
    if (analysis.status == .unique) { var count: usize = 0; const solution = &analysis.solutions[0]; for (answer.cells[0..puzzle.width * puzzle.height], solution.cells[0..puzzle.width * puzzle.height]) |state, value| { if (state != .unknown and state != value) count += 1; } text.add(" differs={d}", .{count}); }
    var lines: C.Lines = .{}; lines.write(text.value()); inline for (.{ true, false }) |is_row| { const numbers = if (is_row) rows.items else columns.items; const clues = if (is_row) puzzle.rows else puzzle.columns; const length = if (is_row) puzzle.width else puzzle.height; for (numbers) |number| { const cells = answer.line(is_row, number - 1); const expected = C.formatted(clues[number - 1], ","); if (partial) lines.add("mismatch {s} expected={s} cells={s}", .{ P.lineLabel(is_row, number - 1), expected, R.stateString(cells[0..length]) }) else lines.add("mismatch {s} expected={s} got={s}", .{ P.lineLabel(is_row, number - 1), expected, C.formatted(C.run(cells[0..length]), ",") }); } } return .{ .result = result, .lines = lines };
}
const Report = struct { puzzle: *Puzzle, status: Status, difficulty: Difficulty, line_solves: usize, guesses: usize, max_depth: usize, solutions: usize, simple_known: usize, logic_known: usize, grading: []const u8 };
const BuiltReport = struct { report: *Report, paragraph: C.Lines };
fn buildReport(puzzle: *Puzzle) BuiltReport {
    var analysis = analyze(puzzle.rows, puzzle.columns, puzzle.givens); defer analysis.deinit(); const simple_result = solvingResult(&analysis.simple_grid, analysis.simple); const logic_result = solvingResult(&analysis.logic_grid, analysis.logic); var lines: C.Lines = .{};
    lines.add("PUZZLE {s}", .{puzzle.name}); lines.add("size={d}x{d} givens={d} status={s} difficulty={s}", .{ puzzle.width, puzzle.height, puzzle.givens.len, @tagName(analysis.status), difficultyText(analysis.difficulty) }); lines.add("clues {s}", .{clueStatistics(puzzle.rows, puzzle.columns)}); lines.add("simple known={d} line_solves={d} result={s}", .{ analysis.simple_grid.known(), analysis.simple.steps.items.len, simple_result }); lines.add("logic known={d} line_solves={d} result={s}", .{ analysis.logic_grid.known(), analysis.logic.steps.items.len, logic_result }); lines.add("steps {s}", .{stepStatistics(analysis.logic)});
    if (puzzle.width * puzzle.height <= 49) { const parts = C.alloc([]const u8, analysis.logic.steps.items.len); for (analysis.logic.steps.items, parts) |step, *part| part.* = step.text(); lines.add("trace {s}", .{C.join(parts, " ")}); }
    if (C.eq(logic_result, "stuck")) lines.add("stuck rows={s} columns={s}", .{ unknownSummary(&analysis.logic_grid, true), unknownSummary(&analysis.logic_grid, false) });
    if (analysis.status == .contradiction) { const step = analysis.logic.conflict.?; const clue = if (step.is_row) puzzle.rows[step.index] else puzzle.columns[step.index]; const count = if (step.is_row) puzzle.width else puzzle.height; const cells = analysis.logic_grid.line(step.is_row, step.index); lines.add("conflict line={s} clue={s} cells={s}", .{ step.label(), C.formatted(clue, ","), R.stateString(cells[0..count]) }); }
    if (analysis.search) |search| { lines.add("search guesses={d} max_depth={d} backtracks={d} solutions={d} line_solves={d}", .{ search.guesses.items.len, search.max_depth, search.backtracks, search.solutions.items.len, search.line_solves }); for (search.guesses.items) |guess| { const outcome = if (guess.outcome == .contradiction) C.fmt("contradiction at={s}", .{guess.conflict.?.label()}) else @tagName(guess.outcome); lines.add("guess {d} depth={d} cell={d},{d} value={c} solves={d} known={d} result={s}", .{ guess.number, guess.depth, guess.position.row + 1, guess.position.column + 1, R.stateChar(guess.value), guess.solves, guess.known, outcome }); } }
    if (analysis.status == .multiple) { const positions = differing(&analysis.solutions[0], &analysis.solutions[1]); const parts = C.alloc([]const u8, positions.len); for (positions, parts) |position, *part| part.* = C.fmt("{d},{d}", .{ position.row + 1, position.column + 1 }); lines.add("differ count={d} cells={s}", .{ positions.len, C.join(parts, " ") }); }
    var names: std.ArrayList([]const u8) = .empty; var grids: std.ArrayList(*const P.Grid) = .empty;
    if (analysis.status == .contradiction) { C.append([]const u8, &names, "partial"); C.append(*const P.Grid, &grids, &analysis.logic_grid); } else { if (C.eq(simple_result, "stuck")) { C.append([]const u8, &names, "simple"); C.append(*const P.Grid, &grids, &analysis.simple_grid); } if (C.eq(logic_result, "stuck")) { C.append([]const u8, &names, "logic"); C.append(*const P.Grid, &grids, &analysis.logic_grid); } if (analysis.status == .multiple) { C.append([]const u8, &names, "first"); C.append([]const u8, &names, "second"); C.append(*const P.Grid, &grids, &analysis.solutions[0]); C.append(*const P.Grid, &grids, &analysis.solutions[1]); } }
    if (names.items.len > 0) lines.extend(R.gridDisplay(names.items, grids.items)); if (analysis.status == .unique) { lines.write("sheet"); lines.extend(R.answerSheet(puzzle.rows, puzzle.columns, &analysis.solutions[0])); lines.add("picture {s}", .{featuresText(&analysis.solutions[0])}); }
    if (evaluateGivens(puzzle, analysis.status)) |evaluation| lines.write(evaluation); var grading: []const u8 = "-"; if (puzzle.answer != null) { const grade = gradeAnswer(puzzle, &analysis); grading = grade.result; lines.extend(grade.lines); }
    const report = C.create(Report, .{ .puzzle = puzzle, .status = analysis.status, .difficulty = analysis.difficulty, .line_solves = analysis.line_solves, .guesses = analysis.guesses, .max_depth = analysis.max_depth, .solutions = analysis.solutions.len, .simple_known = analysis.simple_grid.known(), .logic_known = analysis.logic_grid.known(), .grading = grading }); return .{ .report = report, .paragraph = lines };
}
fn score(report: *const Report) usize { return report.line_solves + 25 * report.guesses; }
fn rankLess(_: void, a: *Report, b: *Report) bool { if (a.difficulty != b.difficulty) return @intFromEnum(a.difficulty) < @intFromEnum(b.difficulty); if (score(a) != score(b)) return score(a) < score(b); return std.mem.order(u8, a.puzzle.name, b.puzzle.name) == .lt; }
const PuzzleOutputs = struct { reports: []const *Report, solutions: C.Lines, stats: C.Lines };
fn processPuzzles(blocks: []const C.Strings) PuzzleOutputs {
    var earlier: std.StringHashMapUnmanaged(void) = .empty; var reports: std.ArrayList(*Report) = .empty; var solutions: C.Lines = .{}; var stats: C.Lines = .{}; stats.write("puzzle,status,difficulty,width,height,givens,simple_known,logic_known,line_solves,guesses,max_depth,solutions,answer"); var invalid: usize = 0;
    for (blocks) |block| { const puzzle = parsePuzzle(block); const reason = validate(puzzle, earlier); earlier.put(C.allocator, puzzle.name, {}) catch @panic("allocation failed");
        if (reason) |error_text| { invalid += 1; var paragraph: C.Lines = .{}; paragraph.add("PUZZLE {s}", .{puzzle.name}); paragraph.add("error {s}", .{error_text}); solutions.paragraph(paragraph); var text: C.Text = .{}; text.add("{s},invalid", .{puzzle.name}); for (0..11) |_| text.write(",-"); stats.write(text.value()); } else { const built = buildReport(puzzle); C.append(*Report, &reports, built.report); solutions.paragraph(built.paragraph); const report = built.report; stats.add("{s},{s},{s},{d},{d},{d},{d},{d},{d},{d},{d},{d},{s}", .{ puzzle.name, @tagName(report.status), difficultyText(report.difficulty), puzzle.width, puzzle.height, puzzle.givens.len, report.simple_known, report.logic_known, report.line_solves, report.guesses, report.max_depth, report.solutions, report.grading }); }
    }
    var ranked: std.ArrayList(*Report) = .empty; var statuses = [_]usize{0} ** 4; var difficulties = [_]usize{0} ** 3; var line_solves: usize = 0; var guesses: usize = 0; for (reports.items) |report| { statuses[@intFromEnum(report.status)] += 1; if (report.difficulty != .unavailable) difficulties[@intFromEnum(report.difficulty)] += 1; line_solves += report.line_solves; guesses += report.guesses; if (report.status == .unique) C.append(*Report, &ranked, report); }
    std.mem.sort(*Report, ranked.items, {}, rankLess); var ranking: C.Lines = .{}; ranking.write("RANKING"); for (ranked.items, 1..) |report, i| ranking.add("rank {d} {s} {s} score={d} size={d}x{d}", .{ i, report.puzzle.name, difficultyText(report.difficulty), score(report), report.puzzle.width, report.puzzle.height }); solutions.paragraph(ranking); var summary: C.Lines = .{}; summary.add("SUMMARY puzzles={d} invalid={d} contradiction={d} none={d} unique={d} multiple={d} easy={d} medium={d} hard={d} line_solves={d} guesses={d}", .{ blocks.len, invalid, statuses[0], statuses[1], statuses[2], statuses[3], difficulties[0], difficulties[1], difficulties[2], line_solves, guesses }); solutions.paragraph(summary); return .{ .reports = reports.items, .solutions = solutions, .stats = stats };
}
fn validatePicture(name: []const u8, rows: C.Strings, earlier: std.StringHashMapUnmanaged(void)) ?[]const u8 { if (!validName(name)) return "bad name"; if (earlier.contains(name)) return "duplicate name"; if (rows.len < 1 or rows.len > 30) return "bad height"; const width = rows[0].len; for (rows, 1..) |row, i| { if (row.len < 1 or row.len > 30 or row.len != width or !validStates(row, false)) return C.fmt("bad row {d}", .{i}); } return null; }
fn sameClues(a: C.Clues, b: C.Clues) bool { if (a.len != b.len) return false; for (a, b) |first, second| { if (!std.mem.eql(usize, first, second)) return false; } return true; }
fn givenLess(_: void, a: Given, b: Given) bool { return if (a.row == b.row) a.column < b.column else a.row < b.row; }
const Generation = struct { paragraph: C.Lines, unique: bool, logic: bool, hints: usize };
fn generatePicture(name: []const u8, grid: *const P.Grid, reports: []const *Report) Generation {
    const rows = C.alloc(C.Clue, grid.height); const columns = C.alloc(C.Clue, grid.width); for (rows, 0..) |*clue, r| { const cells = grid.line(true, r); clue.* = C.run(cells[0..grid.width]); } for (columns, 0..) |*clue, c| { const cells = grid.line(false, c); clue.* = C.run(cells[0..grid.height]); }
    var givens: std.ArrayList(Given) = .empty; var current = analyze(rows, columns, givens.items); const initial_status = current.status; const initial_difficulty = current.difficulty; const initial_solves = current.line_solves; const initial_guesses = current.guesses; var log: C.Lines = .{};
    while (current.status == .multiple) { const position = firstDifference(&current.solutions[0], &current.solutions[1]); const value = grid.get(position.row, position.column); C.append(Given, &givens, .{ .row = position.row, .column = position.column, .value = value }); current.deinit(); current = analyze(rows, columns, givens.items); log.add("# hint {d} cell={d},{d} value={c} status={s}", .{ givens.items.len, position.row + 1, position.column + 1, R.stateChar(value), @tagName(current.status) }); }
    current.deinit(); const original = C.allocator.dupe(Given, givens.items) catch @panic("allocation failed"); for (original) |given| { var index: usize = 0; while (givens.items[index].row != given.row or givens.items[index].column != given.column) index += 1; const others = without(givens.items, index); var candidate = analyze(rows, columns, others); const remove = candidate.status == .unique; candidate.deinit(); if (remove) { givens = .empty; for (others) |other| C.append(Given, &givens, other); log.add("# drop cell={d},{d}", .{ given.row + 1, given.column + 1 }); } }
    current = analyze(rows, columns, givens.items); var added: usize = 0; while (current.difficulty == .hard) { const position = Q.guessCell(&current.logic_grid); const value = grid.get(position.row, position.column); C.append(Given, &givens, .{ .row = position.row, .column = position.column, .value = value }); current.deinit(); current = analyze(rows, columns, givens.items); added += 1; log.add("# logic hint {d} cell={d},{d} value={c} difficulty={s}", .{ added, position.row + 1, position.column + 1, R.stateChar(value), difficultyText(current.difficulty) }); }
    var duplicate: []const u8 = "-"; for (reports) |report| { const puzzle = report.puzzle; if (sameClues(puzzle.rows, rows) and sameClues(puzzle.columns, columns)) { duplicate = puzzle.name; break; } }
    var paragraph: C.Lines = .{}; paragraph.add("# picture {s} size={d}x{d} {s}", .{ name, grid.width, grid.height, featuresText(grid) }); paragraph.add("# clues {s} duplicate_of={s}", .{ clueStatistics(rows, columns), duplicate }); paragraph.add("# plain status={s} difficulty={s} line_solves={d} guesses={d}", .{ @tagName(initial_status), difficultyText(initial_difficulty), initial_solves, initial_guesses }); paragraph.extend(log); paragraph.add("# final status={s} difficulty={s} hints={d} line_solves={d} guesses={d}", .{ @tagName(current.status), difficultyText(current.difficulty), givens.items.len, current.line_solves, current.guesses }); paragraph.add("PUZZLE {s}", .{name}); paragraph.add("SIZE {d} {d}", .{ grid.width, grid.height }); paragraph.write("ROWS"); for (rows) |clue| paragraph.write(C.formatted(clue, " ")); paragraph.write("COLUMNS"); for (columns) |clue| paragraph.write(C.formatted(clue, " ")); std.mem.sort(Given, givens.items, {}, givenLess); for (givens.items) |given| paragraph.add("GIVEN {d} {d} {c}", .{ given.row + 1, given.column + 1, R.stateChar(given.value) }); paragraph.write("END"); current.deinit(); return .{ .paragraph = paragraph, .unique = initial_status == .unique, .logic = initial_difficulty == .easy or initial_difficulty == .medium, .hints = givens.items.len };
}
fn processPictures(blocks: []const C.Strings, reports: []const *Report) C.Lines { var earlier: std.StringHashMapUnmanaged(void) = .empty; var result: C.Lines = .{}; var invalid: usize = 0; var unique: usize = 0; var logic: usize = 0; var hinted: usize = 0; var hints: usize = 0;
    for (blocks) |block| { const name = block[0][8..]; const rows = block[1..]; const reason = validatePicture(name, rows, earlier); earlier.put(C.allocator, name, {}) catch @panic("allocation failed"); if (reason) |error_text| { invalid += 1; var paragraph: C.Lines = .{}; paragraph.add("# picture {s} error {s}", .{ name, error_text }); result.paragraph(paragraph); continue; } const grid = gridFromText(rows); const generation = generatePicture(name, &grid, reports); result.paragraph(generation.paragraph); if (generation.unique) unique += 1; if (generation.logic) logic += 1; if (generation.hints > 0) hinted += 1; hints += generation.hints; }
    var summary: C.Lines = .{}; summary.add("# SUMMARY pictures={d} invalid={d} unique={d} line_logic={d} hinted={d} hints={d}", .{ blocks.len, invalid, unique, logic, hinted, hints }); result.paragraph(summary); return result;
}
pub fn main(init: std.process.Init) !void {
    var arena = std.heap.ArenaAllocator.init(init.gpa); defer arena.deinit(); C.allocator = arena.allocator(); C.backing = init.gpa; const dir = std.Io.Dir.cwd(); const puzzles_text = try dir.readFileAlloc(init.io, "input/puzzles.txt", C.allocator, .unlimited); const pictures_text = try dir.readFileAlloc(init.io, "input/pictures.txt", C.allocator, .unlimited); const outputs = processPuzzles(readBlocks(puzzles_text)); const generated = processPictures(readBlocks(pictures_text), outputs.reports); try dir.createDirPath(init.io, "output"); const names = [_][]const u8{ "solutions.txt", "stats.csv", "generated.txt" }; const reports = [_]C.Lines{ outputs.solutions, outputs.stats, generated }; for (names, reports) |name, report| try dir.writeFile(init.io, .{ .sub_path = C.fmt("output/{s}", .{name}), .data = report.content() });
}
